"use strict";

exports.createSuite = function createSuite() {
  const tests = [];
  return {
    test(name, fn) {
      tests.push({ name, fn });
    },
    async run() {
      let passed = 0;
      let failed = 0;
      for (const entry of tests) {
        try {
          await entry.fn();
          passed += 1;
        } catch (error) {
          failed += 1;
        }
      }
      return { total: tests.length, passed, failed };
    },
  };
};
